def main():
    limit, speed = map(int, input().split())
    if speed <= limit:
        print("No Fine")
    elif speed - limit <= 10:
        print("Fine: 100")
    elif speed - limit <= 25:
        print("Fine: 250")
    else:
        print(f"Fine: {250 + (speed - limit - 25) * 20}")


main()

